                "SELECT t " +
                "FROM Tag AS t " +
                "WHERE t.name LIKE :name")
})
@XmlRootElement
@JsonFilter("custom")
@JsonNaming(value = PropertyNamingStrategy.LowerCaseWithUnderscoresStrategy.class)
public class Tag {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
