    private static final ImmutableMap<Pattern, String> LISTS = ImmutableMap.<Pattern, String>builder()
            .put(Pattern.compile("^-\\s+"), "- ")
            .put(Pattern.compile("^• +"), "- ")
            .put(Pattern.compile("^" + String.valueOf(Character.toChars(8211)) + "\\s+"), "- ")
