public class ActivitiesImporter extends AbstractBatchJob {

    private static final Logger LOGGER = LoggerFactory.getLogger(ActivitiesImporter.class);
    private File tempFolder;
    private String crawlerUser;
    private SessionFactory sessionFactory;
    private long abortTime;

    public ActivitiesImporter(File tempFolder, String crawlerUser, SessionFactory sessionFactory, long abortTime) {
        this.tempFolder = tempFolder;
        this.crawlerUser = crawlerUser;
        this.sessionFactory = sessionFactory;
        this.abortTime = abortTime;
    }

    @Override
    public void run() {
        ActivityDao activityDao = new ActivityDao(sessionFactory);
        UserDao userDao = new UserDao(sessionFactory);
        MediaFileDao mediaFileDao = new MediaFileDao(sessionFactory);

        try {
            DataAccessUtils.runInTransaction(sessionFactory, () -> {

                List<ActivityProperties> remoteActivities = new AktivitetsbankenCrawler(new DefaultWebPageLoader(tempFolder)).readAllActivities();

                Map<String, List<Activity>> localActivitiesByURL = getLocalActivities(activityDao);

                User crawlerUser = DataAccessUtils.getUser(userDao, this.crawlerUser);

                for (ActivityProperties remoteActivity : remoteActivities) {
                    remoteActivity.setAuthor(crawlerUser);

                    // Try to find suitable media files (images) to illustrate the activity. Do this by looking for media
                    // resources with keywords matching the name of the current activity.
                    if (remoteActivity.getMediaFiles().isEmpty()) {
                        String activitiyKeyword = MediaFile.getSimplifiedKeyword(remoteActivity.getName());
                        List<MediaFile> imagesBasedOnActivityName = mediaFileDao.byKeyword(activitiyKeyword);
                        if (!imagesBasedOnActivityName.isEmpty()) {
                            remoteActivity.setMediaFiles(imagesBasedOnActivityName);
                        }
                    }

                    String remoteSource = remoteActivity.getSource();
                    if (localActivitiesByURL.containsKey(remoteSource)) {
                        List<Activity> activitiesForRemoteSource = localActivitiesByURL.get(remoteSource);
                        if (activitiesForRemoteSource.size() == 1) {
                            Activity activity = activitiesForRemoteSource.get(0);
                            if (!activity.getProperties().isContentEqual(remoteActivity)) {
                                activityDao.update(activity, remoteActivity, true, true, false);
                                LOGGER.info("Updated activity {} based on {}", activity.getId(), remoteSource);
                            } else {
                                LOGGER.debug("Ignored activity {} because no properties would have been updated.", activity.getId());
                            }
                        } else {
                            LOGGER.info("For some reason, there are multiple activities created from this URL: {}", remoteSource);
                        }
                    } else {
                        Activity createdActivity = activityDao.create(new Activity(remoteActivity), true, true);
                        LOGGER.info("Created activity {} based on {}", createdActivity.getId(), remoteSource);
                    }

                    if (System.currentTimeMillis() > abortTime) {
                        LOGGER.info("The job's time limit has been exceeded and no more activities will be processed");
                        break;
                    }
                }
                return null;
            });
        } catch (Exception e) {
            LOGGER.warn("Exception when crawling Aktivitetsbanken.", e);
        }
    }

    private Map<String, List<Activity>> getLocalActivities(ActivityDao activityDao) {
        List<Activity> localActivities = activityDao.all();
        return localActivities.stream()
                .filter(activity -> StringUtils.isNotEmpty(activity.getProperties().getSource()))
                .collect(Collectors.groupingBy(activity -> activity.getProperties().getSource()));
    }

    public static class Task extends io.dropwizard.servlets.tasks.Task {
        private File crawlerTempFolder;
        private String crawlerUser;
        private SessionFactory sessionFactory;

        public Task(File crawlerTempFolder, String crawlerUser, SessionFactory sessionFactory) {
            super("auto-import");
            this.crawlerTempFolder = crawlerTempFolder;
            this.crawlerUser = crawlerUser;
            this.sessionFactory = sessionFactory;
        }

        @Override
        public void execute(ImmutableMultimap<String, String> params, PrintWriter printWriter) throws Exception {
            int maxExecutionTimeSeconds = getMaxExecutionTime(params);
            long abortTime = System.currentTimeMillis() + (maxExecutionTimeSeconds * 1000);
            new ActivitiesImporter(
                    crawlerTempFolder,
                    crawlerUser,
                    sessionFactory,
                    abortTime)
                    .run();

        }

        private int getMaxExecutionTime(ImmutableMultimap<String, String> params) {
            int maxExecutionTimeSeconds = 60;
            ImmutableCollection<String> customLimit = params.get("maxExecutionTimeSeconds");
            if (!customLimit.isEmpty()) {
                String max = customLimit.asList().get(0);
                try {
                    maxExecutionTimeSeconds = Integer.parseInt(max);
                } catch (NumberFormatException e) {
                    LOGGER.info("Someone tried to start task 'auto-import' with an incorrect parameter value: {}", max);
                }
            }
            return maxExecutionTimeSeconds;
        }
    }
}

public class GoogleAuthenticator extends AbstractAuthenticator implements Authenticator<String, AuthResult> {

    public static final String ID = "Google";
    private static final Logger LOGGER = LoggerFactory.getLogger(GoogleAuthenticator.class);
    private final Configuration configuration;

    public GoogleAuthenticator(SessionFactory sessionFactory, Configuration configuration) {
        super(sessionFactory);
        this.configuration = configuration;
    }

    @Override
    public Optional<AuthResult> authenticate(String credentials) throws AuthenticationException {
        LOGGER.info("Request authentication started");
        String idToken = credentials;
        String accessToken = null;

        Verify.VerificationResponse idStatus = new Verify(
                configuration.getClientId(),
                configuration.getAcceptedApplicationIds()
        ).verify(idToken, accessToken);

        LOGGER.info("Id token verification result: {}", idStatus.id_token_status.message);

        Optional<AuthResult> result;

        if (idStatus.id_token_status.valid) {
            LOGGER.info("Google id token is valid");
            Transaction tx = createTransaction();
            String gplusId = idStatus.id_token_status.gplus_id;
            User user = getUserDao().readUserByIdentity(IdentityType.GOOGLE, gplusId);
            if (user == null) {
                LOGGER.info("User needs to be added to system.");
                User newUser = new User();
                String name = idStatus.id_token_status.getName();
                String email = idStatus.id_token_status.getEmail();
                newUser.setName(name != null ? name : (email != null ? email : "scout"));
                newUser.setEmailAddress(email);
                newUser.addIdentity(IdentityType.GOOGLE, gplusId);
                getUserDao().create(newUser);

                user = newUser;
                LOGGER.info("New user will be added to system.");
            }
            if (!user.isApiKeySet()) {
                user.addIdentity(IdentityType.API, RandomStringUtils.randomAlphanumeric(50));
                getUserDao().update(user);
                LOGGER.info("API key created for user {}.", user.getName());
            }
            tx.commit();
//            result = Optional.fromNullable(new AuthResult(ID, user));
            result = Optional.ofNullable(new AuthResult(ID, user));
        } else {
            LOGGER.info("Invalid id token");
//            result = Optional.absent();
            result = Optional.empty();
        }
        closeSessionIfNecessary();
        return result;
    }
}

@Path("/v1/activities")
@Produces(MediaType.APPLICATION_JSON)
@Api(tags = {"activities"})
public class ActivityResourceV1 extends se.devscout.scoutapi.resource.ActivityResource {

    private static final Joiner COMMA_COINER = Joiner.on(',').skipNulls();

    public ActivityResourceV1(ActivityDao dao, ActivityRatingDao activityRatingDao) {
        super(dao, activityRatingDao);
    }

    @GET
    @Timed
    @UnitOfWork
    @ApiOperation(value = "Search for activities")
    public Response all(@ApiParam(value = "The activity attributes to include in the response")//, example = "id,name,tags")
                        @QueryParam("attrs") String attrs,
                        @QueryParam("name") String name,

                        @ApiParam(value = "Words to look for in any text field. Prefix word with minus character to exclude activities with that word.")//, example = "mat -matematik")
                        @QueryParam("text") String text,

                        @ApiParam(value = "Show featured (hand-picked by editor) activities")
                        @QueryParam("featured") Boolean featured,

                        @ApiParam(value = "Show activites with at least one of the specified tags. Comma-separated list of category ids.")//, example = "12,34")
                        @QueryParam("categories") String tagIds,
                        @QueryParam("age_1") String age1,
                        @QueryParam("age_2") String age2,

                        @ApiParam(value = "Find activities suited for certain number of participants.")//, example = "1,5")
                        @QueryParam("participants") String numberOfParticipants,
                        @QueryParam("time_1") String time1,
                        @QueryParam("time_2") String time2,
                        @QueryParam("id") String activityIds,

                        @ApiParam(value = "Limit result to activities which the current user (as determined by API key) has marked as favourites.")
                        @QueryParam("my_favourites") Boolean myFavourites,

                        @ApiParam(value = "Show activities which have been rated by at least this many users")
                        @QueryParam("ratings_count_min") Long ratingsCountMin,

                        @ApiParam(value = "Show activities whose average rating is at this amount.")//, example = "1.0")
                        @QueryParam("ratings_average_min") Double ratingsAverageMin,

                        @ApiParam(value = "Limit result to a number of random activities matching the other conditions.")
                        @QueryParam("random") int random,

                        @ApiParam(value = "Limit result to the overall favourite activities. This means a list of activities sorted by the number of users who have marked them as their favourites. This parameter cannot be used together with any other filtering parameters (meaning that it is not possible to use it to, for example, show favourites for a particular category or age group).")
                        @QueryParam("favourites") int favourites) {
        if (myFavourites != null) {
            throw new WebApplicationException("API currently does not support filtering on your own favourites.");
        }
        return okResponse(getActivities(name,
                text,
                featured,
                tagIds,
                COMMA_COINER.join(age1, age2),
                numberOfParticipants,
