@Path("/v1/favourites")
@Produces(MediaType.APPLICATION_JSON)
@Api(tags = {"user content"})
public class FavouritesResourceV1 extends AbstractResource {

    private final ActivityRatingDao activityRatingDao;
    private final ActivityDao activityDao;

    public FavouritesResourceV1(ActivityRatingDao activityRatingDao, ActivityDao activityDao) {
        this.activityRatingDao = activityRatingDao;
        this.activityDao = activityDao;
    }

    @GET
    @Timed
    @UnitOfWork
    public List<Long> get(@Auth @ApiParam(hidden = true) AuthResult authResult , @Context HttpServletResponse response, @PathParam("id") long id) {
        doAuth(authResult, response, Permission.rating_set_own);
        return activityRatingDao.all(authResult.getUser()).stream().filter(ar -> ar.isFavourite() != null && ar.isFavourite()).map(activityRating -> activityRating.getActivity().getId()).collect(Collectors.toList());
    }

    @POST
    @Timed
    @Produces(MediaType.APPLICATION_JSON)
    @UnitOfWork
    public void put(@Auth @ApiParam(hidden = true) AuthResult authResult , @Context HttpServletResponse response, @PathParam("id") long id, PutFavouritesEntity properties) {
        doAuth(authResult, response, Permission.rating_set_own);
        activityRatingDao.all(authResult.getUser()).forEach(activityRating -> {
            boolean shouldBeSetAsFavourite = properties.getIdList().stream().anyMatch(aLong -> aLong == activityRating.getActivity().getId());
            boolean isFavourite = activityRating.isFavourite() != null && activityRating.isFavourite().booleanValue();
            if (shouldBeSetAsFavourite != isFavourite) {
                activityRating.setFavourite(shouldBeSetAsFavourite);
                activityRatingDao.update(activityRating);
            }
            properties.getIdList().remove(activityRating.getActivity().getId());
        });
        properties.getIdList().forEach(aLong -> {
            Activity activity = activityDao.read(aLong);
            if (activity != null) {
                activityRatingDao.create(new ActivityRating(activity, authResult.getUser(), null, true));
            }
        });
    }

    public static class PutFavouritesEntity {
        private List<Long> id;

        public PutFavouritesEntity() {
        }

        public PutFavouritesEntity(List<Long> id) {
            this.id = id;
        }

        @JsonProperty("id")
        public List<Long> getIdList() {
            return id;
        }

        public void setId(List<Long> id) {
            this.id = id;
        }
    }
}

public class RelatedActivitiesUpdater extends AbstractBatchJob {

    private static final NumberFormat NUMBER_FORMAT;
    private static final double FREE_MEMORY_LIMIT = 0.3;
    private static final int NUMBER_OF_REPORT_FILES_PER_RUN = 3;

    static {
        NUMBER_FORMAT = NumberFormat.getNumberInstance();
        NUMBER_FORMAT.setMaximumFractionDigits(2);
        NUMBER_FORMAT.setMinimumFractionDigits(2);
    }

    private static final Logger LOGGER = LoggerFactory.getLogger(RelatedActivitiesUpdater.class);
    private Configuration configuration;
    private SessionFactory sessionFactory;
    private long abortTime;

    public RelatedActivitiesUpdater(Configuration configuration, SessionFactory sessionFactory, long abortTime) {
        this.configuration = configuration;
        this.sessionFactory = sessionFactory;
        this.abortTime = abortTime;
    }

    private static class ActivityMetadataComparatorWeight {
        private ActivityMetadataComparator comparator;
        private double weight;

        public ActivityMetadataComparatorWeight(ActivityMetadataComparator comparator, double weight) {
            this.comparator = comparator;
            this.weight = weight;
        }
    }

    @Override
    public void run() {

        ActivityDao activityDao = new ActivityDao(sessionFactory);

        UserDao userDao = new UserDao(sessionFactory);

        String prefix = new SimpleDateFormat("yyyyMMdd-HHmmss").format(new Date());
        configuration.reportFolder.mkdirs();

        Session session = sessionFactory.openSession();
        ManagedSessionContext.bind(session);

        try {
            List<ActivityMetadata> activities = new ArrayList<>();
            runInTransaction(session, () -> {
                activityDao.all().stream().map(activity -> new ActivityMetadata(activity)).forEach(activityMetadata -> activities.add(activityMetadata));
            });

            if (configuration.simplifyVocabulary) {
                LOGGER.info("Simplifying vocabulary");

                Simplifier.Metadata metadata = simplifyVocabulary(activities, configuration.simplifyRules, configuration.minimumWordGroupSize);

                if (configuration.reportFilesRetentionLimit > 0) {
                    transformReport(metadata, "simplifications.xsl", new File(configuration.reportFolder, prefix + ".SimplifierMetadata.html"));
                }
            }

            ActivityMetadataComparatorWeight[] comparatorWeights = new ActivityMetadataComparatorWeight[]{
                    new ActivityMetadataComparatorWeight(new AllTextComparator(), configuration.comparatorFactorAllText),
                    new ActivityMetadataComparatorWeight(new NameTextComparator(), configuration.comparatorFactorName),
                    new ActivityMetadataComparatorWeight(new MaterialTextComparator(), configuration.comparatorFactorMaterials),
                    new ActivityMetadataComparatorWeight(new IntroductionTextComparator(), configuration.comparatorFactorIntroduction),
                    new ActivityMetadataComparatorWeight(new CategoryComparator(), configuration.comparatorFactorCategories),
                    new ActivityMetadataComparatorWeight(new AgeComparator(), configuration.comparatorFactorAge),
                    new ActivityMetadataComparatorWeight(new ParticipantCountComparator(), configuration.comparatorFactorParticipantCount),
                    new ActivityMetadataComparatorWeight(new TimeComparator(), configuration.comparatorFactorTime)
            };

            LOGGER.info("Generating reports");

            Report report = new Report();
            report.comparatorValuesLabels = createComparatorValuesLabels(comparatorWeights);

            final User crawlerUser = DataAccessUtils.getUser(userDao, configuration.getRelationOwner());

            session.clear();

            runInTransaction(session, () -> {
                long lastFreeMemory = Runtime.getRuntime().freeMemory();
                for (int i = 0; i < activities.size(); i++) {

                    ActivityMetadata metadata = activities.get(i);

                    long freeMemory = Runtime.getRuntime().freeMemory();
                    LOGGER.info(String.format("Calculating related activities for activity %5d, %3d percent done. Memory: total %10d, max %10d, free %10d, free diff %12d",
                            metadata.id,
                            (int) (100.0 * i / activities.size()),
                            Runtime.getRuntime().totalMemory(),
                            Runtime.getRuntime().maxMemory(),
                            freeMemory,
                            freeMemory - lastFreeMemory));

                    ActivityComparisonResult[] comparisons = getComparisonValues(activities, comparatorWeights, i);

                    Report.Activity relation = createReportRelation(activities, configuration.maxRelated, comparisons, metadata);

                    report.activities.add(relation);

                    activityDao.setActivityRelations(crawlerUser,
                            relation.id,
                            relation.relations.stream()
                                    .map(relation1 -> Long.valueOf(relation1.id))
                                    .toArray(length -> new Long[length]));

                    checkMemoryConsumtion();

                    if (System.currentTimeMillis() > abortTime) {
                        LOGGER.info("The job's time limit has been exceeded and no more activities will be processed");
                        break;
                    }

                    Thread.currentThread().yield();

                    lastFreeMemory = freeMemory;
                }
            });

            checkMemoryConsumtion();

            if (configuration.reportFilesRetentionLimit > 0) {
                transformReport(report, "report.xsl", new File(configuration.reportFolder, prefix + ".Report.html"));
                transformReport(report, "report-simpletext.xsl", new File(configuration.reportFolder, prefix + ".SimpleReport.txt"));
            }

        } catch (Throwable e) {
            LOGGER.warn("Exception when calculating similar activities.", e);
        } finally {
            if (session != null) {
                session.close();
            }
            purgeReportFiles();
        }
    }

    protected void purgeReportFiles() {
        if (configuration.reportFilesRetentionLimit > 0) {
            try {
                Files.list(configuration.reportFolder.toPath())
                        .map(p -> p.toFile())
                        .sorted((o1, o2) -> Long.compare(o2.lastModified(), o1.lastModified()))
                        .skip(configuration.reportFilesRetentionLimit * NUMBER_OF_REPORT_FILES_PER_RUN)
                        .forEach(File::delete);
                LOGGER.debug("Removed old report files");
            } catch (IOException e) {
                LOGGER.warn("Could not remove old report files", e);
            }
        }
    }

    protected void checkMemoryConsumtion() {
        if (1.0 * Runtime.getRuntime().freeMemory() / Runtime.getRuntime().totalMemory() < FREE_MEMORY_LIMIT) {
            LOGGER.info("Free memory is less than 30% of the total memory. Application will request the JVM to perform garbage collection.");
            System.gc();
        }
    }

    private void runInTransaction(Session session, Runnable runnable) {
        Transaction tx = null;
        try {
            tx = session.beginTransaction();

            runnable.run();

            tx.commit();
        } catch (Exception e) {
            LOGGER.warn("Exception when calculating similar activities.", e);
            if (tx != null) {
                tx.rollback();
            }
        }
    }

    public Simplifier.Metadata simplifyVocabulary(List<ActivityMetadata> activities, SimplifyRule[] simplifyRules, int minimumWordGroupSize) throws IOException, JAXBException {
        Simplifier simplifier = new Simplifier(getAllWords(activities), simplifyRules, minimumWordGroupSize);

        for (ActivityMetadata activityMetadata : activities) {
            activityMetadata.simplifyVocabulary(simplifier);
        }

        return simplifier.getMetadata();
    }

    private List<String> getAllWords(List<ActivityMetadata> activities) {
        ArrayList<String> allWords = new ArrayList<>();
        for (ActivityMetadata revision : activities) {
            Collections.addAll(allWords, revision.getAllWords());
        }
        return allWords;
    }

    private Report.Activity createReportRelation(List<ActivityMetadata> activities, int maxRelated, ActivityComparisonResult[] comparisons, ActivityMetadata currentRevision) {
        Report.Activity relation = new Report.Activity(
                currentRevision.name,
                currentRevision.id);

        Arrays.sort(comparisons, (o1, o2) -> Double.compare(o2.comparatorValues[0], o1.comparatorValues[0]));

        for (int i = 0; i < Math.min(comparisons.length, maxRelated); i++) {
            ActivityComparisonResult comparison = comparisons[i];
            String[] formattedComparisonValues = new String[comparison.comparatorValues.length];
            for (int j = 0; j < comparison.comparatorValues.length; j++) {
                Double comparisonValue = comparison.comparatorValues[j];
                formattedComparisonValues[j] = NUMBER_FORMAT.format(comparisonValue);
            }
            ActivityMetadata activity = activities.get(comparison.activityId);
            relation.add(new Report.Activity.Relation(
                    createComparatorValues(comparison.comparatorValues),
                    activity.name,
                    activity.id
            ));
        }
        return relation;
    }

    private static class ActivityComparisonResult {
        private int activityId;
        private double[] comparatorValues;

        public ActivityComparisonResult(int activityId, double[] comparatorValues) {
            this.activityId = activityId;
            this.comparatorValues = comparatorValues;
        }
    }

    private ActivityComparisonResult[] getComparisonValues(List<ActivityMetadata> allActivities, ActivityMetadataComparatorWeight[] comparators, int sourceActivityIndex) {
        ActivityMetadata sourceActivityMetadata = allActivities.get(sourceActivityIndex);
        ActivityComparisonResult[] comparisons = new ActivityComparisonResult[allActivities.size()];
        for (int j = 0; j < allActivities.size(); j++) {
            double[] compare = new double[1 + comparators.length];
            if (sourceActivityIndex != j) {
                compare[0] = 0.0;
                int x = 0;
                for (ActivityMetadataComparatorWeight entry1 : comparators) {
                    compare[++x] = entry1.weight > 0 ? entry1.weight * entry1.comparator.compare(sourceActivityMetadata, allActivities.get(j)) : 0;
                    compare[0] += compare[x];
                }
            } else {
                Arrays.fill(compare, 0.0);
            }
            comparisons[j] = new ActivityComparisonResult(j, compare);
        }
        return comparisons;
    }

    private void transformReport(Object o, String xslResourceName, File outputFile) throws ParserConfigurationException, JAXBException, TransformerException, FileNotFoundException {
        Marshaller reportMarshaller = null;
        reportMarshaller = JAXBContext.newInstance(o.getClass()).createMarshaller();
        reportMarshaller.setProperty(Marshaller.JAXB_FORMATTED_OUTPUT, Boolean.TRUE);

        if (xslResourceName != null) {
            Transformer transformer = TransformerFactory.newInstance().newTransformer(new StreamSource(getClass().getResourceAsStream(xslResourceName)));
            Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
            reportMarshaller.marshal(o, doc);
            transformer.transform(new DOMSource(doc), new StreamResult(new FileOutputStream(outputFile)));
        } else {
            reportMarshaller.marshal(o, outputFile);
        }
    }

    private String[] createComparatorValuesLabels(ActivityMetadataComparatorWeight[] comparators) {
        String[] strings = new String[1 + comparators.length];
        int x = 0;
        strings[x++] = "=";
        for (ActivityMetadataComparatorWeight comparator : comparators) {
            strings[x++] = comparator.comparator.toString();
        }
        return strings;
    }

    private String[] createComparatorValues(double[] values) {
        String[] strings = new String[values.length];
        for (int i = 0; i < values.length; i++) {
            strings[i] = NUMBER_FORMAT.format(values[i]);
        }
        return strings;
    }
}

public class MediaFileUtils {

    private static final Pattern RESIZED_FILE_NAME_PATTERN = Pattern.compile("^(.*)\\.(\\w+)_(\\d+).(\\w+)$");
    private static final Logger LOGGER = LoggerFactory.getLogger(MediaFileUtils.class);

    public static void initMediaFileMetaData(MediaFile mediaFile, InputStream inputStream, String defaultName) throws ImageProcessingException, IOException {
        // Try reading image metadata.
        Metadata metadata = ImageMetadataReader.readMetadata(inputStream);

        IptcDirectory iptcData = metadata.getFirstDirectoryOfType(IptcDirectory.class);
        ExifIFD0Directory exifData = metadata.getFirstDirectoryOfType(ExifIFD0Directory.class);

        mediaFile.setCaptureDate(Stream
                        .of(
                                iptcData.getDate(IptcDirectory.TAG_DATE_CREATED),
                                exifData.getDate(ExifIFD0Directory.TAG_DATETIME_ORIGINAL),
                                exifData.getDate(ExifIFD0Directory.TAG_DATETIME))
                        .filter(Objects::nonNull)
                        .findFirst()
                        .orElse(null)
        );

        mediaFile.setCopyRight(Stream
                        .of(
                                iptcData.getString(IptcDirectory.TAG_COPYRIGHT_NOTICE),
                                exifData.getString(ExifIFD0Directory.TAG_ARTIST),
                                exifData.getString(ExifIFD0Directory.TAG_WIN_AUTHOR))
                        .filter(Objects::nonNull)
                        .findFirst()
                        .orElse(null)
        );

        mediaFile.setAuthor(Stream
                        .of(
                                exifData.getString(ExifIFD0Directory.TAG_ARTIST),
                                iptcData.getString(IptcDirectory.TAG_CONTACT))
                        .filter(Objects::nonNull)
                        .findFirst()
                        .orElse(null)
        );

        mediaFile.setName(Stream
                        .of(
                                iptcData.getString(IptcDirectory.TAG_HEADLINE),
                                iptcData.getString(IptcDirectory.TAG_CAPTION),
                                iptcData.getString(IptcDirectory.TAG_BY_LINE_TITLE),
                                defaultName)
                        .filter(Objects::nonNull)
                        .findFirst()
                        .orElse(null)
        );

        Stream
                .of(
                        iptcData.getStringArray(IptcDirectory.TAG_KEYWORDS),
                        iptcData.getStringArray(IptcDirectory.TAG_CATEGORY),
                        iptcData.getStringArray(IptcDirectory.TAG_SUPPLEMENTAL_CATEGORIES))
                .filter(Objects::nonNull)
                .flatMap(Arrays::stream)
                .filter(keyword -> !Strings.isNullOrEmpty(keyword))
                .map(MediaFile::getSimplifiedKeyword)
                .forEach(keyword -> mediaFile.getKeywords().add(keyword));
    }

    public static File getOriginalMediaFile(File file) {
        Matcher matcher = RESIZED_FILE_NAME_PATTERN.matcher(file.getName());
        if (matcher.matches()) {
            if (matcher.group(2).equals(matcher.group(4)) && Ints.tryParse(matcher.group(3)) != null) {
                return new File(file.getParent(), matcher.group(1) + "." + matcher.group(2));
            }
        }
        return null;
    }

    public static boolean isResizedMediaFile(File file) {
        return getOriginalMediaFile(file) != null;
    }

    public static File getSuitableImage(File source, int size, String formatName) throws IOException {
        size = getNextMultipleOfTwo(size);
        File target = new File(source.getParent(), source.getName() + "_" + size + "." + formatName);

        if (target.isFile()) {
            return target;
        }

        // Use Toolkit.createImage instead of ImageIO.read because of a bug in the JPEG read of ImageIO.
        Image img = Toolkit.getDefaultToolkit().createImage(source.toURI().toURL());
        loadCompletely(img);

        BufferedImage image = toBufferedImage(img);// ImageIO.read(source);
        int type = BufferedImage.TYPE_INT_RGB;

        double resizeFactor = 1.0 * size / Math.max(image.getWidth(), image.getHeight());
        if (resizeFactor < 1.0) {
            int width1 = (int) (resizeFactor * image.getWidth());
            int height1 = (int) (resizeFactor * image.getHeight());
            BufferedImage resizedImage = new BufferedImage(width1, height1, type);
            Graphics2D g = resizedImage.createGraphics();

            g.setComposite(AlphaComposite.Src);
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
            g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            g.drawImage(image, 0, 0, resizedImage.getWidth(), resizedImage.getHeight(), null);
            g.dispose();

            ImageIO.write(resizedImage, formatName, target);

            return target;
        } else {
            // Resized images would be larger than original. NOT good. Do nothing instead.
            return source;
        }
    }

    /**
     * Since some methods like toolkit.getImage() are asynchronous, this
     * method should be called to load them completely.
     */
    // http://stackoverflow.com/a/19687400
    private static void loadCompletely(Image img) {
        MediaTracker tracker = new MediaTracker(new JPanel());
        tracker.addImage(img, 0);
        try {
            tracker.waitForID(0);
        } catch (InterruptedException ex) {
            throw new RuntimeException(ex);
        }
    }

    // http://stackoverflow.com/a/19687400
    private static BufferedImage toBufferedImage(Image img) {
        if (img instanceof BufferedImage) {
            return (BufferedImage) img;
        }

        BufferedImage bimage = new BufferedImage(img.getWidth(null), img.getHeight(null), BufferedImage.TYPE_INT_ARGB);

        bimage.getGraphics().drawImage(img, 0, 0, null);
        bimage.getGraphics().dispose();

        return bimage;
    }

    private static int getNextMultipleOfTwo(int num) {
        int next = 16; // You got to start somewhere are it is very unlikely that images smaller than 16 px will ever be requested.
        while (next < num) {
            next *= 2;
        }
        return next;
    }

    public static class CleanResizedImagesCacheTask extends Task {
        private File mediaFilesFolder;

        public CleanResizedImagesCacheTask(File mediaFilesFolder) {
            super("cache-clear-resized-images");
            this.mediaFilesFolder = mediaFilesFolder;
        }

        @Override
        public void execute(ImmutableMultimap<String, String> immutableMultimap, PrintWriter printWriter) throws Exception {
            Files.list(mediaFilesFolder.toPath())
                    .map(path -> path.toFile())
                    .filter(MediaFileUtils::isResizedMediaFile)
                    .forEach((file) -> {
                        if (file.delete()) {
                            LOGGER.info("Deleted {}", file.getAbsolutePath());
                        } else {
                            LOGGER.info("Could not delete {}", file.getAbsolutePath());
                        }
                    });
        }
    }

    public static class AutoAssignMediaFileToTags extends Task {
        private SessionFactory sessionFactory;
        private File mediaFilesFolder;
        private String crawlerUser;

        public AutoAssignMediaFileToTags(SessionFactory sessionFactory, File mediaFilesFolder, String crawlerUser) {
            super("auto-assign-mediafiles");
            this.sessionFactory = sessionFactory;
            this.mediaFilesFolder = mediaFilesFolder;
            this.crawlerUser = crawlerUser;
        }

        @Override
        public void execute(ImmutableMultimap<String, String> params, PrintWriter printWriter) throws Exception {
            final boolean force = params.containsKey("force") && Boolean.parseBoolean(params.get("force").asList().get(0));

            MediaFileDao mediaFileDao = new MediaFileDao(sessionFactory);

            printWriter.format("Assigning to tags%n");

            DataAccessUtils.runInTransaction(sessionFactory, () -> {
                TagDao tagDao = new TagDao(sessionFactory);
                tagDao.all().stream()
                        .filter(tag -> force || tag.getMediaFile() == null)
                        .forEach(tag -> {
                            List<MediaFile> mediaFiles = mediaFileDao.byKeyword(MediaFile.getSimplifiedKeyword(tag.getName()));
                            for (MediaFile mediaFile : mediaFiles) {
                                try {
                                    URI sourceURI = new URI(mediaFile.getUri());
                                    if (new File(mediaFilesFolder, sourceURI.getPath()).exists()) {
                                        tag.setMediaFile(mediaFile);
                                        tagDao.update(tag);
                                        break;
                                    }
                                } catch (URISyntaxException e) {
                                    LOGGER.warn("Could not parse URI in database", e);
                                }
                            }
                        });
                return null;
            });

            printWriter.format("Assigning to activities%n");

            DataAccessUtils.runInTransaction(sessionFactory, () -> {
                User crawlerUser = DataAccessUtils.getUser(new UserDao(sessionFactory), this.crawlerUser);
                ActivityDao activityDao = new ActivityDao(sessionFactory);
                activityDao.all().stream()
                        .map(Activity::getProperties)
                        .filter(properties -> force || properties.getMediaFiles() == null || properties.getMediaFiles().isEmpty())
                        .forEach(properties -> {
                            List<MediaFile> mediaFiles = mediaFileDao.byKeyword(MediaFile.getSimplifiedKeyword(properties.getName()));
                            ActivityProperties newValues = new ActivityProperties(properties);
                            Collection<MediaFile> updatedMediaFiles = new HashSet<>(newValues.getMediaFiles());
                            for (MediaFile mediaFile : mediaFiles) {
                                try {
                                    URI sourceURI = new URI(mediaFile.getUri());
                                    if (new File(mediaFilesFolder, sourceURI.getPath()).exists()) {
                                        updatedMediaFiles.add(mediaFile);
                                    }
                                } catch (URISyntaxException e) {
                                    LOGGER.warn("Could not parse URI in database", e);
                                }
                            }
                            newValues.setMediaFiles(updatedMediaFiles);
                            newValues.setAuthor(crawlerUser);

                            if (!properties.isContentEqual(newValues)) {
                                activityDao.update(properties.getActivity(), newValues, false, false, true);
                                printWriter.format("Activity %-30s (id %-5d): Updated to have %d media files %n", StringUtils.left(properties.getName(), 30), properties.getActivity().getId(), updatedMediaFiles.size());
                            } else {
                                printWriter.format("Activity %-30s (id %-5d): No change%n", StringUtils.left(properties.getName(), 30), properties.getActivity().getId());
                            }
                        });
                return null;
            });

            printWriter.format("Done%n");
        }
    }
}

public class AbstractAuthenticator {
    private final SessionFactory sessionFactory;
    private UserDao userDao;

    public AbstractAuthenticator(SessionFactory sessionFactory) {
        this.sessionFactory = sessionFactory;
    }

    protected void openSessionIfNecessary() {
        try {
            this.sessionFactory.getCurrentSession();
        } catch (HibernateException e) {
            ManagedSessionContext.bind(this.sessionFactory.openSession());
        }
    }

    protected void closeSessionIfNecessary() {
        Session session = this.sessionFactory.getCurrentSession();
        if (session != null) {
            session.close();
        }
    }

    protected UserDao getUserDao() {
        openSessionIfNecessary();
        if (userDao == null) {
            userDao = new UserDao(this.sessionFactory);
        }
        return userDao;
    }

    protected Transaction createTransaction() {
        openSessionIfNecessary();
        return sessionFactory.getCurrentSession().beginTransaction();
    }
}

