public class Checker {

    private static final Logger LOGGER = LoggerFactory.getLogger(Checker.class);
    private final List<String> acceptedApplicationIds;
    private final String mAudience;
    private final GoogleIdTokenVerifier mVerifier;
    private final JsonFactory mJFactory;
    public Checker(String audience, List<String> acceptedApplicationIds) {
        this.acceptedApplicationIds = acceptedApplicationIds;
        mAudience = audience;
        NetHttpTransport transport = new NetHttpTransport();
        mJFactory = new GsonFactory();
        mVerifier = new GoogleIdTokenVerifier(transport, mJFactory);
    }

    public GoogleIdToken.Payload check(String tokenString) {
        GoogleIdToken.Payload payload = null;
        try {
            GoogleIdToken token = GoogleIdToken.parse(mJFactory, tokenString);
            if (mVerifier.verify(token)) {
                GoogleIdToken.Payload tempPayload = token.getPayload();
                if (!tempPayload.getAudience().equals(mAudience)) {
                    LOGGER.info("Audience mismatch");
                } else if (acceptedApplicationIds != null && !acceptedApplicationIds.isEmpty() && !acceptedApplicationIds.contains(tempPayload.getAuthorizedParty())) {
                    LOGGER.info("Client ID mismatch");
                } else {
                    payload = tempPayload;
                }
            }
        } catch (GeneralSecurityException e) {
            LOGGER.info("Security issue: " + e.getLocalizedMessage());
        } catch (IOException e) {
            LOGGER.info("Network problem: " + e.getLocalizedMessage());
        }
        return payload;
    }
}

public class WordHistogram {
    private final Map<String, Integer> wordCounts = new HashMap<>();
    private Map<String, Double> percentages;

    public void countWord(String word) {
        if (!wordCounts.containsKey(word)) {
            wordCounts.put(word, 1);
        } else {
            wordCounts.put(word, wordCounts.get(word) + 1);
        }
        percentages = null;
    }

    Map<String, Double> getPercentages() {
        if (percentages == null) {
            percentages = new HashMap<>();
            int sum = 0;
            for (Integer count : wordCounts.values()) {
                sum += count;
            }
            for (Map.Entry<String, Integer> entry : wordCounts.entrySet()) {
                percentages.put(entry.getKey(), 1.0 * entry.getValue() / sum);
            }
        }
        return percentages;
    }

    public double compare(WordHistogram that) {
        double sum = 0;
        Map<String, Double> thisPercentages = getPercentages();
        Map<String, Double> thatPercentages = that.getPercentages();
        for (Map.Entry<String, Double> entry : thisPercentages.entrySet()) {
            Double thisPercent = entry.getValue();
            Double thatPercent = thatPercentages.get(entry.getKey());
            if (thatPercent != null) {
                sum += (thisPercent + thatPercent) / 2;
            }
        }
        return sum;
    }

    public Map<String, Integer> getTop(int limit) {
        ArrayList<Map.Entry<String, Integer>> entries = new ArrayList<>(wordCounts.entrySet());
        Collections.sort(entries, (o1, o2) -> o2.getValue().compareTo(o1.getValue()));
        Map<String, Integer> topWords = new TreeMap<>();
        for (int i = 0; i < Math.min(entries.size(), limit); i++) {
            Map.Entry<String, Integer> entry = entries.get(i);
            topWords.put(entry.getKey(), entry.getValue());
        }
        return topWords;
    }
}

public class StringMapXmlAdapter extends XmlAdapter<StringMapXmlAdapter.MapStringString, Map<String, String>> {
    @Override
    public Map<String, String> unmarshal(MapStringString v) throws Exception {
        return null;
    }

    @Override
    public MapStringString marshal(Map<String, String> v) throws Exception {
        MapStringString res = new MapStringString();

        Map<String, List<String>> temp = new HashMap<>();

        for (Map.Entry<String, String> entry : v.entrySet()) {
            String from = entry.getKey();
            String to = entry.getValue();

            if (!temp.containsKey(to)) {
                temp.put(to, new ArrayList<String>());
            }
            temp.get(to).add(from);
        }
        for (Map.Entry<String, List<String>> entry : temp.entrySet()) {
            res.entries.add(new MapStringString.Entry(entry.getValue(), entry.getKey()));
        }
        return res;
    }

    public static class MapStringString {
        @XmlElement(name = "v")
        List<Entry> entries = new ArrayList<>();

        public static class Entry {
            @XmlElement(name = "v")
            List<String> from = new ArrayList<>();
