        return Objects.equals(id, mediaFile.id);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id);
    }

    public static String getSimplifiedKeyword(String keyword) {
        return PATTERN_MULTIPLE_SPACES
                .matcher(
                        PATTERN_NOT_ALPHANUMERICAL_CHARACTERS
                                .matcher(keyword)
                                .replaceAll("")
                )
                .replaceAll(" ")
                .toLowerCase()
                .trim();
    }

